import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`leads`,heroTitle:`Build your outbound pipeline in minutes`,heroSubtitle:`Perplexity Computer finds your ideal prospects, writes personalized outreach for each one, and delivers a launch-ready pipeline — automatically.`,inputUrlCta:`Find leads`,inputUrlPrefill:`Go to {url} and build an outbound lead generation campaign. Analyze the product, value proposition, and ideal customer profile. Find and score 200+ prospects that match. Write personalized outreach sequences for each lead. Deliver a campaign brief with lead scores, outreach copy, and a tracking sheet.`,heroOverlaySteps:[`Analyzing your website for product details and value proposition`,`Sourcing and scoring 200+ prospects that match your ideal customer profile`,`Writing personalized outreach sequences for every lead`,`Assembling campaign brief, lead scores, and tracking sheet — ready to execute`],generatingSteps:[`Visiting {url} to extract your product, pricing, and ideal customer profile`,`Designing an agent to find and score prospects across the web`,`Configuring personalized outreach and follow-up sequences for each lead`,`Setting up connectors for lead scoring, CRM sync, and campaign tracking`],featureSectionTitle:`From website to pipeline`,featureCardTitles:[`Connects to your sales stack`,`Outreach ready to send`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Salesforce, HubSpot, Gmail, Slack — Computer plugs into your tools so prospects flow straight into your CRM.`,`Personalized emails. Multi-step sequences. Follow-up cadences. Computer delivers outreach your team can review and launch immediately.`],capabilitySectionTitle:`Your outbound team, on autopilot`,capabilitySectionSubtitle:`Point it at your website, get back a full pipeline.`,capabilityCards:[{title:`Prospect Research`,description:`Computer finds and scores prospects across the web — company size, role, industry, and buying signals — matched to your ICP.`},{title:`Personalized Sequences`,description:`Computer writes multi-step outreach tailored to each prospect — referencing their company, role, and pain points.`},{title:`Lead Scoring`,description:`Computer ranks every prospect by fit and intent so your team focuses on the leads most likely to convert.`},{title:`CRM & Email Sync`,description:`Computer pushes leads and sequences to Salesforce, HubSpot, Gmail, and more — no manual data entry.`},{title:`Learns Your ICP`,description:`Computer remembers your ideal customer profile, messaging, and past campaigns — so every run gets sharper.`},{title:`Pipeline Monitoring`,description:`Computer tracks replies, opens, and engagement — and alerts you when a lead is ready for a call.`}]});export{t as default};
